'''Streaming compaction acceptance checks.

The fold must keep the reassembled state (parameters, gradients, optimizer
moments and step count, hidden state) bit for bit identical, advance no
optimizer step, drop the segment count by exactly the merged range, leave a
chain with nothing to merge untouched, migrate old-version segments exactly
as load does and re-save them in the current format version, and reject a
missing or corrupt chain with the documented exception types before anything
is written.
'''

import os
import shutil
import struct
import sys
import tempfile

from sequence_engine import Sequential, Tensor
from sequence_engine._selftest import _base_weights, _build, _make_v2_chain, _SEG1

FAILURES = []


def check(condition, message):
    if condition:
        print('ok   ' + message)
    else:
        print('FAIL ' + message)
        FAILURES.append(message)


def seg_name(index):
    return 'seg-%010d.seqd' % index


def seg_count(directory):
    count = 0
    for name in os.listdir(directory):
        if name.startswith('seg-') and name.endswith('.seqd'):
            count += 1
    return count


def head_value(directory):
    with open(os.path.join(directory, 'head'), 'rb') as handle:
        return int(handle.read())


def content_snapshot(directory):
    data = {}
    for name in sorted(os.listdir(directory)):
        if 'lock' in name.lower():
            continue
        path = os.path.join(directory, name)
        if os.path.isfile(path):
            with open(path, 'rb') as handle:
                data[name] = handle.read()
    return data


def truncate_file(path):
    with open(path, 'rb') as handle:
        raw = handle.read()
    with open(path, 'wb') as handle:
        handle.write(raw[: len(raw) // 2])


def new_model():
    model, _ = _build(_base_weights())
    return model


def state_bytes(model):
    buffer = bytearray()
    model.save(buffer)
    return bytes(buffer)


def chain_state(directory):
    model = new_model()

